wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::response_channel;

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        let confirmation = response_channel::send(&reply.text);

        // The ensures clause must hold of every output. The host stamps the
        // session identity and delivery status; the guest cannot fabricate
        // either. If the channel did not confirm delivery, or returned no
        // session identity, trap rather than return an output that violates
        // the contract.
        if !confirmation.delivered {
            panic!("ResponseChannel did not confirm delivery");
        }
        if confirmation.session.is_empty() {
            panic!("ResponseChannel returned no session identity");
        }

        confirmation
    }
}

export!(Node);
